const DICTS = { en: EN, ar: AR };
const Ctx = createContext(null);

export function I18nProvider({ children }) {
  const [lang, setLang] = useState(() => localStorage.getItem('thoth-lang') || 'ar');
  useEffect(() => {
    localStorage.setItem('thoth-lang', lang);
    document.documentElement.lang = lang;
    document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
  }, [lang]);
  const t = useCallback((k, vars) => {
    let s = DICTS[lang][k] ?? EN[k] ?? k;
    if (vars && typeof s === 'string') for (const [a, b] of Object.entries(vars)) s = s.replaceAll('{' + a + '}', b);
    return s;
  }, [lang]);
  // pick a localized field from a {en, ar} object
  const L = useCallback(o => (o && typeof o === 'object' ? (o[lang] || o.en || o.ar || '') : o || ''), [lang]);
  return <Ctx.Provider value={{ lang, setLang, t, L, toggle: () => setLang(l => (l === 'ar' ? 'en' : 'ar')) }}>{children}</Ctx.Provider>;
}
export const useI18n = () => useContext(Ctx);
